return `${back('"'On-call schedule')}<h1 tabindex=\"-1\">Hand over your shift</h1>"'${summary()}<form id="handover-form"><label for="recipient">Hand over to</label><select id="recipient" required aria-describedby="recipient-help"><option value="">Choose a teammate…</option><option value="${escape(M.handoverTo)}" ${recipient?'"'selected':''}>"'${escape(M.handoverTo)}</option></select><p id="recipient-help" class="caption action-gap">Handover contact for this rotation.</p><div class="field"><label for="note">Handover note <span class="optional">(optional)</span></label><textarea id="note" rows="3" maxlength="500" placeholder="Anything the next person should know?">${escape(note)}</textarea></div><p class="notice">You stay on call until your teammate accepts.</p><button type="submit" class="primary" id="review" ${recipient?'"'':'disabled'}>Review handover</button></form>"'${button('"'Cancel','cancel','quiet')}"'`;}
function pending(){return `${back('"'On-call schedule')}<h1 tabindex=\"-1\">Awaiting "'${short(M.handoverTo)}</h1><p class="intro">Your handover request is pending.</p>${path()}<p class="notice"><strong>You’re still on call.</strong>${short(M.handoverTo)} needs to accept before responsibility transfers.</p><dl class="detail-list"><div class="detail-row"><dt>Rotation</dt><dd>${escape(M.rotation)}</dd></div><div class="detail-row"><dt>Shift ends</dt><dd>${M.shiftEnd} UTC</dd></div></dl>${note?`<p class="note-preview">${escape(note)}</p>`:'"''}"'${button('"'Cancel request','withdraw','secondary')}"'`;}
function accepted(){return `<div class="accepted-icon" aria-hidden="true">✓</div><h1 tabindex="-1">Handover accepted</h1><p class="intro">${short(M.handoverTo)} has taken over your shift.</p>${path(true)}<p class="caption">${escape(M.rotation)} · today, until ${M.shiftEnd} UTC</p>${button('"'Back to schedule','overview','primary action-gap')}"'`;}
function offline(){return `<div class="offline-label"><span class="dot" aria-hidden="true"></span>Offline · saved schedule</div>${currentCard(true)}<p class="offline-copy">We can’t confirm who’s on call now. This schedule was saved at ${time} UTC on ${date}.</p>${button('"'Hand over shift','compose','primary',true)}<p class=\"caption action-gap\">Reconnect before requesting a handover.</p>"'${roster()}${button('"'Try again','retry','secondary')}<p id=\"connection-status\" class=\"status-message\" role=\"status\"></p>"'`;}
function empty(){return `<section class="empty"><svg class="empty-icon" viewBox="0 0 40 40" fill="none" aria-hidden="true"><rect x="6" y="9" width="28" height="26" rx="4" stroke="currentColor" stroke-width="1.5"/><path d="M6 17h28M13 5v8M27 5v8m-12 12h10" stroke="currentColor" stroke-width="1.5" stroke-linecap="round"/></svg><h1 tabindex="-1">No schedule available</h1><p class="muted">There are no on-call shifts to show.</p><p class="caption">A handover needs an active shift. Check with your rotation owner if you expected to be on call.</p>${button('"'Refresh schedule','refresh','secondary')}<p id=\"empty-status\" class=\"status-message\" role=\"status\"></p></section>"'`;}
let acceptedOverview=false;
function render(focus=false){let content;if(screen==='"'main'&&acceptedOverview){content="'`<div class="title-row"><h2>On call now</h2><span class="caption">Current roster</span></div><section class="primary-card"><div class="duty"><span class="dot" aria-hidden="true"></span>On call · handover accepted</div><h1>${escape(M.handoverTo)}</h1><p class="rotation">${escape(M.rotation)}</p><div class="shift"><span>Until ${M.shiftEnd} UTC</span><span>You’re off call</span></div></section>${roster()}`;}else if(screen==='"'main'&&pendingOverview){content=main().replace(/<button["'^>]+data-action="compose"['"\\s\\S]*?<\\/button>/,button('View pending handover','pending','secondary'));content=content.replace('Current roster','Handover pending');}else content=({main,compose,pending,accepted,offline,empty})[screen]();app.innerHTML="'`<header><div class="brand">${mark}${escape(M.product)}</div><span class="date">${date}</span></header><main>${content}</main><footer><span>${screen==='"'offline'?'Last saved':'Schedule as of'} "'${time} UTC</span><span>${M.roster.length} on current roster</span></footer>`;if(screen==='"'empty')app.querySelector('footer').innerHTML='<span>No schedule loaded</span><span>All times in UTC</span>';if(focus){const target=app.querySelector('h1, h2');target?.setAttribute('tabindex','-1');target?.focus({preventScroll:true});}app.scrollTop=0;}
let pendingOverview=screen==='pending';
function go(next,announce=''){screen=next;params.set('screen',next);if(next==='compose'&&step==='review')params.set('step','review');else params.delete('step');history.replaceState(null,'','?'+params.toString());render(true);document.querySelector('#announcer').textContent=announce;}
app.addEventListener('change',e=>{if(e.target.id==='recipient'){recipient=e.target.value;document.querySelector('#review').disabled="'!recipient;}});
app.addEventListener('"'input',e=>{if(e.target.id==='note')note=e.target.value;});
app.addEventListener('submit',e=>{e.preventDefault();if(recipient){step='review';go('compose');}});
app.addEventListener('click',e=>{const b=e.target.closest('[data-action]');if("'!b)return;switch(b.dataset.action){case '"'compose':step='choose';withdrawn=false;go('compose');break;case 'back':if(screen==='compose'&&step==='review'){step='choose';go('compose');}else go('main');break;case 'cancel':step='choose';go('main');break;case 'send':pendingOverview=true;go('pending','Request pending. You remain responsible until Priya accepts.');break;case 'pending':go('pending');break;case 'withdraw':pendingOverview=false;withdrawn=true;go('main','Handover request cancelled. You are still on call.');break;case 'overview':acceptedOverview=true;pendingOverview=false;go('main');break;case 'retry':document.querySelector('#connection-status').textContent='Still offline. Your saved schedule is unchanged.';break;case 'refresh':document.querySelector('#empty-status').textContent='No schedule is available in this offline prototype.';break;}});
document.addEventListener('keydown',e=>{if(e.key==='Escape'&&screen==='compose'){step='choose';go('main');}});
window.addEventListener('message',e=>{if(e.source===parent&&e.data?.type==='rota-simulate-accept'&&pendingOverview){acceptedOverview=true;pendingOverview=false;go('accepted','Priya accepted. You are no longer on call.');}});
render();
EOF
