'use strict';
const F = window.EVAL_FIXTURES, M = F.menu;
const params = new URLSearchParams(location.search);
const states = ['main','compose','pending','offline','empty','accepted'];
let screen = states.includes(params.get('screen')) ? params.get('screen') : 'main';
let step = params.get('step') === 'review' ? 'review' : 'choose';
let recipient = step === 'review' ? M.handoverTo : '', note = '', withdrawn = false;
const app = document.querySelector('#app');
const media = matchMedia('(prefers-color-scheme: dark)');
function theme(){document.documentElement.dataset.theme = ['light','dark'].includes(params.get('theme')) ? params.get('theme') : media.matches ? 'dark' : 'light';}
theme();media.addEventListener('change',theme);
const escape = s => String(s).replace(/[&<>\"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','\"':'&quot;',\"'\":'&#39;'}[c]));
