const initials = s=>s.split(' ').map(x=>x[0]).join('');
const date = new Date(F.now).toLocaleDateString('en-GB',{weekday:'short',day:'numeric',month:'short',timeZone:'UTC'});
const time = new Date(F.now).toLocaleTimeString('en-GB',{hour:'2-digit',minute:'2-digit',timeZone:'UTC'});
const mark = '<svg class=\"mark\" viewBox=\"0 0 24 24\" fill=\"none\" aria-hidden=\"true\"><path d=\"M3 7h15m-4-4 4 4-4 4M21 17H6m4-4-4 4 4 4\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"/></svg>';
function button(text,action,cls='primary',disabled=false){return "'`<button type="button" class="${cls}" data-action="${action}" ${disabled?'"'disabled':''}>"'${text}</button>`;}
function back(text='"'Back'){return button("'`‹ &nbsp; ${text}`,'"'back','back');}
function summary(){return "'`<div class="shift-summary"><strong>${escape(M.rotation)}</strong><span class="muted">Today, ${M.shiftStart}–${M.shiftEnd} UTC</span></div>`;}
function path(accepted=false){return `<div class="handover" aria-label="Responsibility transfer"><div class="handover-person ${accepted?'"'':'current'}\"><span class=\"dot\" aria-hidden=\"true\"></span><div><strong>"'${escape(M.user)} <span class="optional">(you)</span></strong><div class="caption">${accepted?'"'Handed over':'Responsible now'}</div></div></div><div class=\"connector\" aria-hidden=\"true\"></div><div class=\"handover-person "'${accepted?'"'current':''}\"><span class=\"dot\" aria-hidden=\"true\"></span><div><strong>"'${escape(M.handoverTo)}</strong><div class="caption">${accepted?'"'Responsible now · until '+M.shiftEnd+' UTC':'Responsible after acceptance'}</div></div></div></div>"'`;}
function roster(){return `<div class="section-heading"><h2>Also on call</h2><span class="caption">Until ${M.shiftEnd} UTC</span></div><ul class="roster">${M.roster.filter(p=>p.name!==M.user).map(p=>`<li class="person"><span class="avatar" aria-hidden="true">${initials(p.name)}</span><div class="person-info"><div class="person-name">${escape(p.name)}</div><div class="caption">${escape(p.role)}</div></div></li>`).join('"'')}</ul>"'`;}
function currentCard(offline=false){return `<section class="primary-card ${offline?'"'offline-card':''}\" aria-label=\""'${offline?'"'Last-known shift':'Your current shift'}\"><div class=\"duty\"><span class=\"dot\" aria-hidden=\"true\"></span>"'${offline?'"'Last known on call':'You’re on call'}</div><h1>"'${escape(M.user)}</h1><p class="rotation">${escape(M.rotation)}</p><div class="shift"><span>${M.shiftStart}–${M.shiftEnd} UTC</span><span>${offline?'"'Scheduled until':'Ends at'} "'${M.shiftEnd}</span></div></section>`;}
function main(){return `<div class="title-row"><h2>On call now</h2><span class="caption">Current roster</span></div>${currentCard()}${button('"'Hand over shift <span class=\"arrow\" aria-hidden=\"true\">→</span>','compose','primary action-gap')}"'${withdrawn?'"'<p class=\"status-message\" role=\"status\">Request cancelled. You’re still on call.</p>':''}"'${roster()}`;}
function compose(){if(step==='"'review')return "'`${back('"'Edit handover')}<h1 tabindex=\"-1\">Review handover</h1><p class=\"intro\">"'${escape(M.rotation)} · until ${M.shiftEnd} UTC</p>${path()}<p class="notice">Sending a request won’t end your shift. You stay responsible until ${short(M.handoverTo)} accepts.</p>${note?`<div class="caption">Handover note</div><p class="note-preview">${escape(note)}</p>`:'"''}"'${button('"'Send handover request','send','primary action-gap')}"'${button('"'Cancel','cancel','quiet')}"'`;
